<?php defined('BASEPATH') or exit('No direct script access allowed');init_head(); ?><div id="wrapper"><div class="content"><div class="panel_s"><div class="panel-body"><h4><i class="fa fa-calculator"></i> <?= _l('scct_calculator'); ?></h4><input id="scCalc" class="form-control input-lg" readonly><div class="sc-calc-grid"><?php foreach(['7','8','9','/','4','5','6','*','1','2','3','-','0','.','C','+'] as $k){echo '<button type="button" class="btn btn-default" data-k="'.$k.'">'.$k.'</button>';} ?></div><button class="btn btn-success btn-block" id="scEq">=</button></div></div></div></div><script>document.querySelectorAll('[data-k]').forEach(b=>b.onclick=()=>{let i=document.getElementById('scCalc');b.dataset.k==='C'?i.value='':i.value+=b.dataset.k});document.getElementById('scEq').onclick=()=>{let i=document.getElementById('scCalc');try{i.value=Function('return '+i.value)()}catch(e){i.value='Error'}};</script><style>.sc-calc-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:12px 0}.sc-calc-grid .btn{font-size:20px;padding:14px}</style><?php init_tail(); ?>
